public class RepeatingCycleFinder {

    public static int cycleLength(int d) {
        String digits = cycleDigits(d);
        if (d < 1) {
            return -1;
        }
        return digits.length();
    }

    public static String cycleDigits(int d) {
        if (d < 1) {
            return "";
        }
        int[] firstSeenAt = new int[d];
        for (int i = 0; i < d; i++) {
            firstSeenAt[i] = -1;
        }
        StringBuilder digits = new StringBuilder();
        int remainder = 1 % d;
        while (remainder != 0 && firstSeenAt[remainder] == -1) {
            firstSeenAt[remainder] = digits.length();
            digits.append((char) ('0' + (remainder * 10) / d));
            remainder = (remainder * 10) % d;
        }
        if (remainder == 0) {
            return "";
        }
        return digits.substring(firstSeenAt[remainder]);
    }
}
